// splitNameMatch is the shared scan of set and remove: one pass finds the
// first fragment matching name (empty fragments never match) and keeps every
// other fragment — non-matching parameters, duplicates and empty fragments —
// in its place with its existing bytes. The matching fragments are dropped
// from kept; their count tells the caller whether the name was present. The
// first hit stays at items[first], so a set merging the name keeps the
// position by overwriting kept[first] in place.
func splitNameMatch(items []queryItem, name string) (first int, kept []queryItem) {
	first = -1
	kept = items[:0]
	for k, it := range items {
		if it.matches(name) {
			if first < 0 {
				first = k
			}
			continue
		}
		kept = append(kept, it)
	}
	return first, kept
